CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS companies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, legal_name TEXT, business_type TEXT, iec TEXT, pan TEXT, country TEXT DEFAULT 'IN', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS parties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), party_type TEXT NOT NULL, name TEXT NOT NULL, country TEXT, address TEXT, registration_identifier TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reference_no TEXT UNIQUE NOT NULL, company_id UUID REFERENCES companies(id), product_type TEXT NOT NULL, status TEXT NOT NULL, currency TEXT, declared_value NUMERIC(20,4), counterparty_id UUID REFERENCES parties(id), transaction_date DATE, effective_date DATE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS export_contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), contract_reference TEXT, contract_date DATE, currency TEXT, contract_value NUMERIC(20,4), payment_terms TEXT, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS export_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), invoice_number TEXT NOT NULL, invoice_date DATE, currency TEXT, invoice_value NUMERIC(20,4), payment_terms TEXT, buyer_id UUID REFERENCES parties(id), description TEXT, status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), payment_type TEXT NOT NULL, direction TEXT NOT NULL, reference TEXT, currency TEXT, amount NUMERIC(20,4), payment_date DATE, counterparty TEXT, purpose_code TEXT, bank_reference TEXT, status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS irms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), irm_reference TEXT, currency TEXT, amount NUMERIC(20,4), date DATE, purpose_code TEXT, bank_reference TEXT, status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS export_shipments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), shipping_bill_number TEXT, shipping_bill_date DATE, port TEXT, export_date DATE, currency TEXT, export_value NUMERIC(20,4), invoice_id UUID REFERENCES export_invoices(id), status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), transaction_id UUID REFERENCES transactions(id), document_type TEXT, file_name TEXT, storage_key TEXT, mime_type TEXT, file_size BIGINT, version INT DEFAULT 1, status TEXT, uploaded_by UUID, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(), verified_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS reconciliations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), source_type TEXT, source_id UUID, target_type TEXT, target_id UUID, allocated_amount NUMERIC(20,4), currency TEXT, status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS regulatory_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rule_code TEXT NOT NULL, authority TEXT, title TEXT, description TEXT, product_type TEXT, effective_from DATE, effective_to DATE, version TEXT, conditions JSONB, actions JSONB, source_reference TEXT, status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS declarations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), declaration_type TEXT, version INT DEFAULT 1, status TEXT, prepared_at TIMESTAMPTZ, reviewed_at TIMESTAMPTZ, submitted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS declaration_fields (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), declaration_id UUID NOT NULL REFERENCES declarations(id), field_name TEXT, field_value TEXT, source_type TEXT, source_id UUID, customer_confirmed BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS actions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), transaction_id UUID REFERENCES transactions(id), action_type TEXT, priority TEXT, title TEXT, description TEXT, reason TEXT, recommended_action TEXT, due_date DATE, status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), user_id UUID, entity_type TEXT, entity_id UUID, action TEXT, old_value JSONB, new_value JSONB, ip_address INET, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_transactions_reference ON transactions(reference_no);
CREATE INDEX IF NOT EXISTS idx_documents_transaction ON documents(transaction_id);
CREATE INDEX IF NOT EXISTS idx_payments_transaction ON payments(transaction_id);
